+    atom.m_Type         = type;
+    atom.m_Offset       = offset;
+    atom.m_Payload      = offset+header_size;
+    atom.m_DeclaredSize = size;
+    atom.m_SizeIsValid  = size >= header_size && offset+size <= region_end &&
