+        AP4_UI32 media_timescale = recovery->m_MediaTimeScale ?
+                                   recovery->m_MediaTimeScale : 1;
+        AP4_UI64 movie_duration = AP4_ConvertTime(media_duration,
+                                                  media_timescale,
