+---------------------------------------------------------------------*/
#define BANNER "MP4 File Repair - Version 1.0\n"\
               "(Bento4 Version " AP4_VERSION_STRING ")\n"\
               "(c) 2002-2026 Axiomatic Systems, LLC"

/*----------------------------------------------------------------------
|   types
+---------------------------------------------------------------------*/
struct AtomRef {
    AtomRef() :
        m_Type(0),
        m_Offset(0),
        m_Payload(0),
        m_End(0),
        m_DeclaredSize(0),
        m_SizeIsValid(false) {}

    AP4_UI32     m_Type;
    AP4_UI64     m_Offset;
    AP4_UI64     m_Payload;
    AP4_UI64     m_End;
    AP4_UI64     m_DeclaredSize;
    bool         m_SizeIsValid;
};

struct SampleRecord {
    AP4_UI64 m_Offset;
    AP4_UI32 m_Size;
    AP4_UI64 m_Dts;
    AP4_UI32 m_Duration;
    AP4_UI32 m_CtsDelta;
    bool     m_IsSync;
};

struct TrackRecovery {
    TrackRecovery() :
        m_HandlerType(0),
        m_MediaTimeScale(0),
        m_MediaDuration(0),
        m_Width(0),
        m_Height(0),
        m_SampleDescription(NULL),
        m_SampleDescriptionIsOwned(true),
        m_SampleDataStream(NULL),
        m_DefaultDuration(0),
        m_DescriptionIndex(0) {}

    ~TrackRecovery() {
        if (m_SampleDescriptionIsOwned) delete m_SampleDescription;
        if (m_SampleDataStream) m_SampleDataStream->Release();
    }

    AP4_UI32                  m_HandlerType;
    AP4_UI32                  m_MediaTimeScale;
    AP4_UI64                  m_MediaDuration;
    AP4_UI32                  m_Width;
    AP4_UI32                  m_Height;
