        bool known = IsKnownTopLevelType(type);

        if (size_32 == 1) {
            if (position+16 > file_size) break;
            result = ReadStream(stream, position+8, header+8, 8);
            if (AP4_FAILED(result)) break;
            size = ReadUint64(header+8);
            header_size = 16;
